@RunWith(MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_createExterns_TriageGen1Test {

    @Spy
    private AbstractCommandLineRunner runner = new AbstractCommandLineRunner() {
        @Override
        protected Compiler createCompiler() {
            return null;
        }

        @Override
        protected CompilerOptions createOptions() {
            return null;
        }

        @Override
        protected DiagnosticGroups getDiagnosticGroups() {
            return null;
        }

        @Override
        protected void initOptionsFromFlags(CompilerOptions options) {
        }

        @Override
        protected void setRunOptions(CompilerOptions options) throws FlagUsageException, IOException {
        }

        // Mocking the internal access to config if needed, 
        // but since createExterns calls createExternInputs (which is likely a method in the same class),
        // we must spy on the runner to control createExternInputs behavior.
    };

    @Mock
    private CommandLineConfig mockConfig;

    @Mock
    private JSSourceFile mockFile1;

    @Mock
    private JSSourceFile mockFile2;

    @Before
    public void setUp() throws Exception {
        // Use reflection or setter if config is private/protected to inject mockConfig
        // For the purpose of this test, we assume the runner uses the config field.
        java.lang.reflect.Field configField = AbstractCommandLineRunner.class.getDeclaredField("config");
        configField.setAccessible(true);
        configField.set(runner, mockConfig);
    }

    /**
     * Since createExterns calls createExternInputs (a protected method in the same class),
     * and we want to test the logic of createExterns specifically, we spy the runner
     * to stub createExternInputs.
     */
    @Test
    public void testCreateExterns_Success() throws Exception {
        List<JSSourceFile> expectedFiles = ImmutableList.of(mockFile1, mockFile2);

        // We need to use a spy of the runner to stub the call to createExternInputs
        AbstractCommandLineRunner spyRunner = org.mockito.Mockito.spy(runner);

        // Stub createExternInputs to return our list
        // Note: In a real scenario, createExternInputs is likely a method in AbstractCommandLineRunner
        // We use doReturn to avoid calling the real method which might depend on config.externs
        doReturn(expectedFiles).when(spyRunner).createExternInputs(mockConfig.externs);

        List<JSSourceFile> actualFiles = spyRunner.createExterns();

        assertThat(actualFiles).isEqualTo(expectedFiles);
        assertThat(actualFiles).hasSize(2);
    }

    @Test
    public void testCreateExterns_ThrowsIOException() throws Exception {
        AbstractCommandLineRunner spyRunner = org.mockito.Mockito.spy(runner);

        doThrow(new IOException("Disk error")).when(spyRunner).createExternInputs(mockConfig.externs);

        try {
            spyRunner.createExterns();
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            assertThat(e.getMessage()).isEqualTo("Disk error");
        }
    }

    @Test
    public void testCreateExterns_ThrowsFlagUsageException() throws Exception {
        AbstractCommandLineRunner spyRunner = org.mockito.Mockito.spy(runner);

        doThrow(new FlagUsageException("Invalid flag")).when(spyRunner).createExternInputs(mockConfig.externs);

        try {
            spyRunner.createExterns();
            org.junit.Assert.fail("Expected FlagUsageException to be thrown");
        } catch (FlagUsageException e) {
            assertThat(e.getMessage()).isEqualTo("Invalid flag");
        }
    }

    @Test
    public void testCreateExterns_EmptyList() throws Exception {
        AbstractCommandLineRunner spyRunner = org.mockito.Mockito.spy(runner);
        doReturn(ImmutableList.of()).when(spyRunner).createExternInputs(mockConfig.externs);

        List<JSSourceFile> actualFiles = spyRunner.createExterns();

        assertThat(actualFiles).isEmpty();
    }
}
